"use client";

import { type NavigationListProps, NavigationList as NavigationListRoot } from "./navigation-list";
import { NavigationListBadge } from "./navigation-list-badge";
import { NavigationListGroup, type NavigationListGroupProps } from "./navigation-list-group";
import { NavigationListItem, type NavigationListItemProps } from "./navigation-list-item";
import { NavigationListMeta, type NavigationListMetaProps } from "./navigation-list-meta";
import {
  NavigationListProgress,
  type NavigationListProgressProps,
} from "./navigation-list-progress";
import { NavigationListStatus, type NavigationListStatusProps } from "./navigation-list-status";
import {
  NavigationListSubtitle,
  type NavigationListSubtitleProps,
} from "./navigation-list-subtitle";
import { NavigationListTitle, type NavigationListTitleProps } from "./navigation-list-title";

const NavigationList = Object.assign(NavigationListRoot, {
  Item: NavigationListItem,
  Badge: NavigationListBadge,
  Title: NavigationListTitle,
  Status: NavigationListStatus,
  Meta: NavigationListMeta,
  Subtitle: NavigationListSubtitle,
  Progress: NavigationListProgress,
  Group: NavigationListGroup,
});

export { NavigationList, type NavigationListProps };
export type { NavigationListIndicator } from "./navigation-list-context";
export { NavigationListItem, type NavigationListItemProps };
export { NavigationListBadge };
export type { BadgeProps as NavigationListBadgeProps } from "../badge/badge";
export { NavigationListTitle, type NavigationListTitleProps };
export { NavigationListStatus, type NavigationListStatusProps };
export { NavigationListMeta, type NavigationListMetaProps };
export { NavigationListSubtitle, type NavigationListSubtitleProps };
export { NavigationListProgress, type NavigationListProgressProps };
export { NavigationListGroup, type NavigationListGroupProps };

"use client";

import {
  type ComponentPropsWithRef,
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import {
  collectListboxItems,
  getEncodedListboxItemId,
  type ListboxMetadataItem,
  useListbox,
} from "@/hooks/use-listbox";
import { isSelectableItemEligible, useSelectableCollection } from "@/lib/selectable-collection";
import { cn } from "@/lib/utils";
import {
  type GroupHeaderRegistration,
  NavigationListContext,
  type NavigationListIndicator,
} from "./navigation-list-context";
import { NavigationListGroup } from "./navigation-list-group";
import { NavigationListItem } from "./navigation-list-item";

export interface NavigationListProps
  extends Omit<ComponentPropsWithRef<"div">, "children" | "onKeyDown" | "onSelect"> {
  /** Controlled selected item id. */
  selectedId?: string | null;
  /** Initial selected id for uncontrolled mode. */
  defaultSelectedId?: string | null;
  /** Controlled highlighted (focused) item id. */
  highlighted?: string | null;
  /** Initial highlighted id for uncontrolled mode. */
  defaultHighlighted?: string | null;
  /** Fired when an item is activated by click, Enter, or Space — including the already-selected item. */
  onSelect?: (id: string) => void;
  /**
   * Fired when Enter activates an item. Receives the raw keyboard event for modifier-key
   * handling.
   */
  onEnter?: (id: string, event: globalThis.KeyboardEvent) => void;
  /** Fired when the highlighted item changes. */
  onHighlightChange?: (id: string | null) => void;
  /**
   * Fired when arrow navigation reaches the first/last item with wrap disabled, enabling
   * cross-list navigation.
   */
  onNavigationBoundaryReached?: (
    direction: "previous" | "next",
    event: globalThis.KeyboardEvent,
    key: string,
  ) => void;
  /** Visual indicator style for the active/selected item. */
  indicator?: NavigationListIndicator;
  /**
   * When false, removes the active visual treatment from the selected/highlighted item (useful
   * when focus is elsewhere).
   */
  focused?: boolean;
  /** When true, arrow navigation wraps at list boundaries. */
  wrap?: boolean;
  /**
   * Enable type-ahead character search to jump to matching items. Disable when
   * every printable key the list's screen advertises belongs to an external
   * hotkey layer.
   * @default true
   */
  typeahead?: boolean;
  /** Auto-focus the list on mount. */
  autoFocus?: boolean;
  /** NavigationList.Item children. */
  children: ReactNode;
  /** Called when key down occurs. */
  onKeyDown?: (event: KeyboardEvent) => void;
}

/**
 * Terminal-styled navigation sidebar list with selection, keyboard navigation, and composable
 * item parts.
 */
export function NavigationList({
  selectedId: controlledSelectedId,
  defaultSelectedId = null,
  highlighted: controlledHighlighted,
  defaultHighlighted = null,
  onSelect,
  onEnter,
  onHighlightChange,
  onNavigationBoundaryReached,
  indicator = "bar",
  focused = true,
  wrap = true,
  typeahead = true,
  autoFocus = false,
  className,
  children,
  onKeyDown,
  "aria-label": ariaLabel,
  ref,
  ...rootProps
}: NavigationListProps) {
  const idPrefix = useId();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const composedRef = useComposedRefs(containerRef, ref);
  const groupHeadersRef = useRef<Map<string, GroupHeaderRegistration>>(new Map());
  const [registrationsStarted, setRegistrationsStarted] = useState(false);
  const {
    items: visibleItems,
    registerItem,
    unregisterItem,
  } = useSelectableCollection(containerRef);
  const visibleMetadata = useMemo<ListboxMetadataItem[]>(
    () =>
      visibleItems.map((item) => ({
        id: item.value,
        disabled: !isSelectableItemEligible(item),
      })),
    [visibleItems],
  );
  const renderSeed = useMemo(
    () =>
      collectListboxItems(children, {
        itemTypes: [NavigationListItem],
        containerTypes: [NavigationListGroup],
      }),
    [children],
  );
  const items = registrationsStarted ? visibleMetadata : renderSeed;

  const handleRegisterItem = useCallback(
    (registrationId: string, value: string, disabled: boolean, element: HTMLElement | null) => {
      setRegistrationsStarted(true);
      registerItem(registrationId, value, disabled, element);
    },
    [registerItem],
  );

  const handleGroupKeyDown = useCallback(
    (event: KeyboardEvent) => {
      onKeyDown?.(event);
      if (event.defaultPrevented) return;

      const key = event.key;
      if (key !== "ArrowLeft" && key !== "ArrowRight" && key !== "Enter" && key !== " ") return;

      const container = containerRef.current;
      if (!container) return;
      const activeId = container.getAttribute("aria-activedescendant");
      if (!activeId) return;

      const activeEl = container.ownerDocument.getElementById(activeId);
      if (!activeEl) return;
      const itemValue = activeEl.dataset.value;
      if (!itemValue) return;

      const registration = groupHeadersRef.current.get(itemValue);
      if (!registration) return;

      if (key === "ArrowRight") {
        if (!registration.expanded) {
          event.preventDefault();
          registration.toggle();
        }
        return;
      }

      if (key === "ArrowLeft") {
        if (registration.expanded) {
          event.preventDefault();
          registration.toggle();
        }
        return;
      }

      if (key === "Enter" || key === " ") {
        event.preventDefault();
        registration.toggle();
      }
    },
    [onKeyDown],
  );

  const { selectedId, highlighted, handleItemActivate, handleItemHighlight, getContainerProps } =
    useListbox({
      selectedId: controlledSelectedId,
      defaultSelectedId,
      highlighted: controlledHighlighted,
      defaultHighlighted,
      onSelect,
      onEnter,
      onHighlightChange,
      onNavigationBoundaryReached,
      wrap,
      idPrefix,
      autoFocus,
      onKeyDown: handleGroupKeyDown,
      typeahead,
      items,
      getItemId: getEncodedListboxItemId,
      ref: composedRef,
    });

  const wrappedActivate = useCallback(
    (id: string) => {
      handleItemActivate(id);
    },
    [handleItemActivate],
  );

  const registerGroupHeader = useCallback((id: string, registration: GroupHeaderRegistration) => {
    groupHeadersRef.current.set(id, registration);
  }, []);

  const unregisterGroupHeader = useCallback((id: string) => {
    groupHeadersRef.current.delete(id);
  }, []);

  const contextValue = useMemo(
    () => ({
      selectedId,
      highlighted,
      activate: wrappedActivate,
      highlight: handleItemHighlight,
      focusContainer: () => containerRef.current?.focus(),
      focused,
      idPrefix,
      indicator,
      registerItem: handleRegisterItem,
      unregisterItem,
      registerGroupHeader,
      unregisterGroupHeader,
    }),
    [
      selectedId,
      highlighted,
      wrappedActivate,
      handleItemHighlight,
      focused,
      idPrefix,
      indicator,
      handleRegisterItem,
      unregisterItem,
      registerGroupHeader,
      unregisterGroupHeader,
    ],
  );

  return (
    <NavigationListContext value={contextValue}>
      {/* biome-ignore lint/a11y/useAriaPropsSupportedByRole: getContainerProps applies role="listbox" dynamically, which Biome cannot resolve; aria-label and aria-orientation are valid for the listbox role. */}
      <div
        {...rootProps}
        {...getContainerProps()}
        data-slot="navigation-list"
        aria-label={ariaLabel}
        aria-orientation="vertical"
        className={cn("w-full outline-none", className)}
      >
        {children}
      </div>
    </NavigationListContext>
  );
}

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import {
  Children,
  type ComponentPropsWithRef,
  type ElementType,
  type FocusEvent,
  isValidElement,
  type MouseEvent,
  type ReactNode,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { getEncodedListboxItemId } from "@/hooks/use-listbox";
import { mergeIds } from "@/lib/aria";
import { MARKER_RAIL_BASE, MARKER_RAIL_ON_INVERTED, MARKER_RAIL_SELECTED } from "@/lib/marker-rail";
import { cn } from "@/lib/utils";
import { useNavigationListContext } from "./navigation-list-context";
import {
  useNavigationListGroupContext,
  useNavigationListGroupPositionContext,
} from "./navigation-list-group-context";
import { NavigationListItemContext } from "./navigation-list-item-context";
import { NavigationListMeta } from "./navigation-list-meta";
import { NavigationListSubtitle } from "./navigation-list-subtitle";
import { NavigationListTitle } from "./navigation-list-title";

const itemVariants = cva("flex cursor-pointer group", {
  variants: {
    active: {
      true: "bg-primary text-primary-foreground",
      false: "hover:bg-secondary border-b border-b-border/50",
    },
    disabled: {
      true: "opacity-50 cursor-not-allowed",
    },
    tree: {
      true: "",
      false: "",
    },
  },
  compoundVariants: [
    { tree: true, active: false, className: "hover:bg-transparent border-b-0" },
    // Disabled rows drop every hover affordance so they never invite a click.
    { disabled: true, active: false, className: "hover:bg-transparent" },
  ],
  defaultVariants: {
    active: false,
    disabled: false,
    tree: false,
  },
});

// Tree rows carry the active/selected fill on an inner wrapper (the outer row
// owns the connector glyph), so the axis lives in its own CVA rather than raw
// ternaries beside itemVariants.
const treeRowVariants = cva("flex-1 flex items-center rounded-sm", {
  variants: {
    active: {
      true: "bg-primary text-primary-foreground",
      // The hover fill lives in the compound below, not here: this CVA is applied raw (no
      // cn()/twMerge pass), so pairing `hover:bg-secondary` with a `hover:bg-transparent`
      // override would ship both classes and leave source order to decide which wins.
      false: "",
    },
    selected: {
      true: "bg-secondary",
      false: "",
    },
    // disabled carries no standalone classes but must be declared so the typed call site can
    // pass it and the compound variant below can match.
    disabled: {
      true: "",
      false: "",
    },
  },
  compoundVariants: [{ active: false, disabled: false, className: "hover:bg-secondary" }],
  defaultVariants: { active: false, selected: false, disabled: false },
});

const contentVariants = cva("flex-1 grid grid-cols-[1fr_auto] auto-rows-auto gap-y-0.5", {
  variants: {
    density: {
      compact: "p-1.5",
      default: "p-3",
      comfortable: "p-5",
    },
  },
  defaultVariants: {
    density: "default",
  },
});

type Density = NonNullable<VariantProps<typeof contentVariants>["density"]>;

function hasChildOfType(children: ReactNode, childType: ElementType): boolean {
  return Children.toArray(children).some((child) => {
    if (!isValidElement<{ children?: ReactNode }>(child)) return false;
    if (child.type === childType) return true;
    return hasChildOfType(child.props.children, childType);
  });
}

function hasStandaloneSubtitle(children: ReactNode): boolean {
  return Children.toArray(children).some((child) => {
    if (!isValidElement<{ children?: ReactNode }>(child)) return false;
    if (child.type === NavigationListSubtitle) return true;
    if (child.type === NavigationListMeta) return false;
    return hasStandaloneSubtitle(child.props.children);
  });
}

export interface NavigationListItemProps
  extends Omit<
    ComponentPropsWithRef<"div">,
    | "id"
    | "children"
    | "role"
    | "aria-selected"
    | "aria-disabled"
    | "aria-labelledby"
    | "aria-describedby"
  > {
  /** Stable identifier matched against selectedId/highlighted. */
  id: string;
  /** Padding scale for the item content. */
  density?: Density;
  /** Disables activation; item is rendered with aria-disabled. */
  disabled?: boolean;
  /** Item subparts (Title, Status, Meta, Badge, Subtitle). */
  children: ReactNode;
}

/** Selectable list item container. */
export function NavigationListItem({
  id,
  disabled = false,
  density = "default",
  children,
  className,
  ref,
  onClick,
  onMouseDown,
  onFocus,
  ...rootProps
}: NavigationListItemProps) {
  const {
    selectedId,
    highlighted,
    activate,
    highlight,
    focusContainer,
    focused,
    idPrefix,
    indicator,
    registerItem,
    unregisterItem,
  } = useNavigationListContext();
  const groupContext = useNavigationListGroupContext();
  const positionContext = useNavigationListGroupPositionContext();
  const registrationId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const composedRef = useComposedRefs(rootRef, ref);
  const isTree = groupContext.variant === "tree" && groupContext.depth > 0;
  const isSelected = !disabled && selectedId === id;
  const isHighlighted = !disabled && highlighted === id;
  const hasHighlight = highlighted !== null;
  const isActive = !disabled && focused && (hasHighlight ? isHighlighted : isSelected);
  const itemId = getEncodedListboxItemId(idPrefix, id);
  const labelId = `${itemId}-label`;
  const descIdPrefix = `${itemId}-desc`;
  // Reference the label only when a Title actually renders it, the same rule the
  // description ids follow: a dangling IDREF is an ARIA violation, and the row's
  // text content is a better fallback name than a pointer to nothing.
  const labelledBy = hasChildOfType(children, NavigationListTitle) ? labelId : undefined;
  const describedBy = mergeIds(
    hasChildOfType(children, NavigationListMeta) ? `${descIdPrefix}-meta` : undefined,
    hasStandaloneSubtitle(children) ? `${descIdPrefix}-sub` : undefined,
  );

  // Selected rows keep a muted marker while the active visual is elsewhere
  // (unfocused list or another highlighted row), mirroring the TUI's
  // always-rendered selected-marker cell.
  const showsSelectedMarker = isSelected && !isActive;

  let indicatorColorClass = disabled ? "bg-transparent" : "bg-transparent group-hover:bg-muted";
  if (isActive) {
    // One inverted-row indicator colour regardless of indicator width, so the mark never means
    // two things.
    indicatorColorClass = "bg-primary-foreground";
  } else if (showsSelectedMarker) {
    indicatorColorClass = "bg-accent";
  }

  const handleClick = (event: MouseEvent<HTMLDivElement>) => {
    onClick?.(event);
    if (event.defaultPrevented || disabled) return;
    activate(id);
    focusContainer();
  };

  const handleMouseDown = (event: MouseEvent<HTMLDivElement>) => {
    onMouseDown?.(event);
    if (event.defaultPrevented) return;
    if (disabled) event.preventDefault();
  };

  const handleFocus = (event: FocusEvent<HTMLDivElement>) => {
    onFocus?.(event);
    if (!event.defaultPrevented && !disabled) highlight(id);
  };

  const itemContextValue = useMemo(
    () => ({ labelId, descIdPrefix, isTree }),
    [labelId, descIdPrefix, isTree],
  );

  useLayoutEffect(() => {
    registerItem(registrationId, id, disabled, rootRef.current);
    return () => unregisterItem(registrationId);
  }, [registerItem, unregisterItem, registrationId, id, disabled]);

  return (
    <NavigationListItemContext value={itemContextValue}>
      {/* biome-ignore lint/a11y/useFocusableInteractive: WAI-ARIA listbox pattern — option stays non-focusable while the navigation list container holds focus and aria-activedescendant tracks the active option. */}
      {/* biome-ignore lint/a11y/useKeyWithClickEvents: Enter/Space activation is handled centrally by the navigation list container, not per option. */}
      <div
        {...rootProps}
        ref={composedRef}
        id={itemId}
        role="option"
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        data-value={id}
        data-highlighted={isActive ? "" : undefined}
        data-selected={isSelected ? "" : undefined}
        aria-selected={isSelected}
        aria-disabled={disabled || undefined}
        onMouseDown={handleMouseDown}
        onClick={handleClick}
        onFocus={handleFocus}
        className={cn(
          itemVariants({ active: isActive, disabled, tree: isTree || undefined }),
          // The library's shared "you are here" mark: a 2px rail for the
          // persistent current location, inversion for the transient highlight,
          // and both together on a row that is currently both. The base class
          // reserves the rail in every state, so the label's x-position never
          // shifts. Tree rows carry their own connector glyph gutter instead.
          !isTree && MARKER_RAIL_BASE,
          !isTree && isActive && MARKER_RAIL_ON_INVERTED,
          !isTree && showsSelectedMarker && MARKER_RAIL_SELECTED,
          showsSelectedMarker && !isTree && "bg-secondary",
          className,
        )}
      >
        {isTree && (
          <span
            aria-hidden="true"
            className="text-muted-foreground font-mono text-sm select-none shrink-0 self-center leading-none"
          >
            {groupContext.linePrefix}
            {positionContext?.isLast ? "└── " : "├── "}
          </span>
        )}
        {isTree ? (
          <div
            className={treeRowVariants({
              active: isActive,
              selected: showsSelectedMarker,
              disabled,
            })}
          >
            <div className="flex-1 grid grid-cols-[1fr_auto] auto-rows-auto gap-y-0.5 py-0.5 px-1">
              {children}
            </div>
          </div>
        ) : (
          <>
            <div
              data-indicator={indicator}
              className={cn(
                "shrink-0",
                (indicator === "bar" || indicator === "bar-thick") && [
                  indicator === "bar" ? "w-1" : "w-2",
                  indicatorColorClass,
                ],
                (indicator === "arrow" || indicator === "bracket") && "w-1 bg-transparent",
              )}
            />
            <div className={contentVariants({ density })}>{children}</div>
          </>
        )}
      </div>
    </NavigationListItemContext>
  );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useNavigationListContext } from "./navigation-list-context";
import { useNavigationListItemContext } from "./navigation-list-item-context";

const INDICATOR_GLYPHS = {
  bar: "\u258C",
  "bar-thick": "\u258C",
  arrow: ">",
  bracket: "[",
} as const;

export interface NavigationListTitleProps {
  /** Primary label. Used as aria-labelledby for the item. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Primary item label. */
export function NavigationListTitle({ children, className }: NavigationListTitleProps) {
  const { labelId, isTree } = useNavigationListItemContext();
  const { indicator } = useNavigationListContext();
  const glyph = INDICATOR_GLYPHS[indicator];

  return (
    <span
      id={labelId}
      className={cn(
        "col-start-1 row-start-1 font-bold flex items-center group-data-[highlighted]:text-primary-foreground",
        className,
      )}
    >
      {!isTree && (
        <span aria-hidden="true" className="mr-2 opacity-30 group-data-[highlighted]:opacity-100">
          {glyph}
        </span>
      )}
      {children}
      {!isTree && indicator === "bracket" && (
        <span aria-hidden="true" className="ml-2 opacity-30 group-data-[highlighted]:opacity-100">
          {"]"}
        </span>
      )}
    </span>
  );
}

"use client";

import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

export interface NavigationListStatusProps extends ComponentPropsWithoutRef<"span"> {
  /** Top-right status marker. */
  children: ReactNode;
}

/** Top-right status marker. */
export function NavigationListStatus({ children, className, ...props }: NavigationListStatusProps) {
  return (
    <span
      {...props}
      className={cn(
        "col-start-2 row-start-1 self-center text-2xs font-bold text-muted-foreground group-data-[highlighted]:text-primary-foreground",
        className,
      )}
    >
      {children}
    </span>
  );
}

"use client";

import { createContext, useContext } from "react";

export type NavigationListIndicator = "bar" | "bar-thick" | "arrow" | "bracket";

export interface GroupHeaderRegistration {
  /** Toggles the group header registration item. */
  toggle: () => void;
  expanded: boolean;
}

export interface NavigationListContextValue {
  /** Controlled selected item id. */
  selectedId: string | null;
  /** Controlled highlighted (focused) item id. */
  highlighted: string | null;
  /** Activates an item in navigation list. */
  activate: (id: string) => void;
  /** Highlights an item in navigation list. */
  highlight: (id: string) => void;
  /** Moves focus to container. */
  focusContainer: () => void;
  /**
   * When false, removes the active visual treatment from the selected/highlighted item (useful
   * when focus is elsewhere).
   */
  focused: boolean;
  idPrefix: string;
  indicator: NavigationListIndicator;
  registerItem: (
    registrationId: string,
    value: string,
    disabled: boolean,
    element: HTMLElement | null,
  ) => void;
  unregisterItem: (registrationId: string) => void;
  registerGroupHeader: (id: string, registration: GroupHeaderRegistration) => void;
  unregisterGroupHeader: (id: string) => void;
}

export const NavigationListContext = createContext<NavigationListContextValue | undefined>(
  undefined,
);

export function useNavigationListContext() {
  const context = useContext(NavigationListContext);
  if (context === undefined) {
    throw new Error("NavigationListItem must be used within NavigationList");
  }
  return context;
}

"use client";

import { cn } from "@/lib/utils";
import { Badge, type BadgeProps } from "../badge/badge";

/** Standardized badge slot (uses Badge primitive) */
export function NavigationListBadge({
  children,
  variant = "neutral",
  size = "sm",
  className,
  ...props
}: BadgeProps) {
  return (
    <Badge
      variant={variant}
      size={size}
      className={cn(
        "group-data-[highlighted]:bg-primary-foreground/15 group-data-[highlighted]:text-primary-foreground group-data-[highlighted]:border-primary-foreground/40",
        className,
      )}
      {...props}
    >
      {children}
    </Badge>
  );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useNavigationListItemContext } from "./navigation-list-item-context";

export interface NavigationListSubtitleProps {
  /** Secondary metadata text. Wired to aria-describedby. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Secondary metadata text. */
export function NavigationListSubtitle({ children, className }: NavigationListSubtitleProps) {
  const { descIdPrefix } = useNavigationListItemContext();

  return (
    <span
      id={`${descIdPrefix}-sub`}
      className={cn(
        "block min-w-0 truncate text-2xs leading-none text-muted-foreground group-data-[highlighted]:text-primary-foreground/70",
        className,
      )}
    >
      {children}
    </span>
  );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useNavigationListItemContext } from "./navigation-list-item-context";

export interface NavigationListMetaProps {
  /** Container for inline metadata (badges, dates). Wired to aria-describedby. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Row 2 container for badges and subtitles. */
export function NavigationListMeta({ children, className }: NavigationListMetaProps) {
  const { descIdPrefix } = useNavigationListItemContext();

  return (
    <div
      id={`${descIdPrefix}-meta`}
      className={cn(
        "col-span-full row-start-2 flex gap-2 items-center group-data-[highlighted]:text-primary-foreground/70",
        className,
      )}
    >
      {children}
    </div>
  );
}

"use client";

import { createContext, useContext } from "react";

export interface NavigationListItemContextValue {
  labelId: string;
  /** Prefix the description parts derive their own ids from, never an id itself. */
  descIdPrefix: string;
  isTree: boolean;
}

export const NavigationListItemContext = createContext<NavigationListItemContextValue | undefined>(
  undefined,
);

export function useNavigationListItemContext() {
  const context = useContext(NavigationListItemContext);
  if (context === undefined) {
    throw new Error("NavigationList.Title/Meta must be used within NavigationList.Item");
  }
  return context;
}

"use client";

import {
  Children,
  type FocusEvent,
  isValidElement,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";
import { useControllableState } from "@/hooks/use-controllable-state";
import { getEncodedListboxItemId } from "@/hooks/use-listbox";
import { cn } from "@/lib/utils";
import { Chevron } from "../icons/chevron";
import { useNavigationListContext } from "./navigation-list-context";
import {
  NavigationListGroupContext,
  NavigationListGroupPositionContext,
  useNavigationListGroupContext,
  useNavigationListGroupPositionContext,
} from "./navigation-list-group-context";

export interface NavigationListGroupProps {
  /** Group header text. */
  label: string;
  /** Controlled expanded state. */
  expanded?: boolean;
  /** Initial expanded state for uncontrolled mode. */
  defaultExpanded?: boolean;
  /** Fired when expanded state changes. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Optional count shown next to the label in section variant. */
  count?: number;
  /**
   * Visual treatment. "section" shows uppercase headers with counts, "tree" shows indented
   * hierarchy with ASCII connectors.
   */
  variant?: "tree" | "section";
  /** Stable header identity. Defaults to a per-instance generated value. */
  headerId?: string;
  /** Accessible action word appended to the header name while collapsed. Defaults to "expand". */
  expandLabel?: string;
  /** Accessible action word appended to the header name while expanded. Defaults to "collapse". */
  collapseLabel?: string;
  /** NavigationList.Item or nested NavigationList.Group children. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Collapsible group with header (section or tree variant) */
export function NavigationListGroup({
  label,
  expanded: controlledExpanded,
  defaultExpanded = true,
  onExpandedChange,
  count,
  variant = "section",
  headerId: controlledHeaderId,
  expandLabel = "expand",
  collapseLabel = "collapse",
  children,
  className,
}: NavigationListGroupProps) {
  const parentGroup = useNavigationListGroupContext();
  const position = useNavigationListGroupPositionContext();
  const generatedId = useId();
  const headerId = controlledHeaderId ?? `__group_${generatedId}`;

  const [expanded, setExpanded] = useControllableState<boolean>({
    value: controlledExpanded,
    defaultValue: defaultExpanded,
    onChange: onExpandedChange,
  });

  const depth = variant === "tree" ? parentGroup.depth + 1 : 0;

  const linePrefix = useMemo(() => {
    if (variant !== "tree") return "";
    if (depth <= 1) return "";
    const isLast = position?.isLast ?? false;
    return parentGroup.linePrefix + (isLast ? "    " : "│   ");
  }, [variant, depth, position?.isLast, parentGroup.linePrefix]);

  const toggle = useCallback(() => setExpanded((prev) => !prev), [setExpanded]);

  const arrayChildren = Children.toArray(children);

  const groupContextValue = useMemo(
    () => ({ variant, depth, linePrefix }),
    [variant, depth, linePrefix],
  );

  const groupLabel = variant === "section" && count !== undefined ? `${label} (${count})` : label;

  const wrappedChildren = (
    <NavigationListGroupContext value={groupContextValue}>
      {/* Children.toArray preserves explicit keys and gives unkeyed elements positional keys. */}
      {arrayChildren.map((child, index) => (
        <NavigationListGroupPositionContext
          key={isValidElement(child) && child.key !== null ? child.key : index}
          value={{ isLast: index === arrayChildren.length - 1 }}
        >
          {child}
        </NavigationListGroupPositionContext>
      ))}
    </NavigationListGroupContext>
  );

  if (variant === "section") {
    return (
      // biome-ignore lint/a11y/useSemanticElements: role="group" labels a related set of navigation options; <fieldset> is for form controls and is not appropriate here.
      <div
        role="group"
        aria-label={groupLabel}
        className={cn("border-t border-border first:border-t-0", className)}
      >
        <NavigationListGroupHeader
          variant="section"
          headerId={headerId}
          label={label}
          count={count}
          expanded={expanded}
          toggle={toggle}
          expandLabel={expandLabel}
          collapseLabel={collapseLabel}
        />
        {expanded && wrappedChildren}
      </div>
    );
  }

  return (
    // biome-ignore lint/a11y/useSemanticElements: role="group" labels a related set of navigation options; <fieldset> is for form controls and is not appropriate here.
    <div role="group" aria-label={groupLabel} className={className}>
      <NavigationListGroupHeader
        variant="tree"
        headerId={headerId}
        label={label}
        expanded={expanded}
        toggle={toggle}
        depth={depth}
        parentLinePrefix={parentGroup.linePrefix}
        isLast={position?.isLast ?? false}
        expandLabel={expandLabel}
        collapseLabel={collapseLabel}
      />
      {expanded && wrappedChildren}
    </div>
  );
}

function useNavigationListGroupHeader({
  headerId,
  expanded,
  toggle,
}: {
  headerId: string;
  expanded: boolean;
  toggle: () => void;
}) {
  const {
    highlighted,
    highlight,
    focusContainer,
    focused,
    idPrefix,
    registerItem,
    unregisterItem,
    registerGroupHeader,
    unregisterGroupHeader,
  } = useNavigationListContext();
  const registrationId = useId();
  const rootRef = useRef<HTMLDivElement>(null);

  const itemId = getEncodedListboxItemId(idPrefix, headerId);
  const isHighlighted = highlighted === headerId;
  const isActive = focused && isHighlighted;

  useLayoutEffect(() => {
    registerItem(registrationId, headerId, false, rootRef.current);
    return () => unregisterItem(registrationId);
  }, [registerItem, unregisterItem, registrationId, headerId]);

  useEffect(() => {
    registerGroupHeader(headerId, { toggle, expanded });
    return () => unregisterGroupHeader(headerId);
  }, [headerId, toggle, expanded, registerGroupHeader, unregisterGroupHeader]);

  const handleClick = (event: MouseEvent<HTMLDivElement>) => {
    event.preventDefault();
    toggle();
    highlight(headerId);
    focusContainer();
  };

  const handleFocus = (event: FocusEvent<HTMLDivElement>) => {
    if (!event.defaultPrevented) highlight(headerId);
  };

  return { rootRef, itemId, isActive, handleClick, handleFocus };
}

function NavigationListGroupHeader({
  variant,
  headerId,
  label,
  count,
  expanded,
  toggle,
  depth = 0,
  parentLinePrefix = "",
  isLast = false,
  expandLabel,
  collapseLabel,
}: {
  variant: "tree" | "section";
  headerId: string;
  label: string;
  count?: number;
  expanded: boolean;
  toggle: () => void;
  depth?: number;
  parentLinePrefix?: string;
  isLast?: boolean;
  expandLabel: string;
  collapseLabel: string;
}) {
  const isTree = variant === "tree";
  const accessibleLabel = isTree || count === undefined ? label : `${label} (${count})`;
  const header = useNavigationListGroupHeader({ headerId, expanded, toggle });

  return (
    // biome-ignore lint/a11y/useFocusableInteractive: WAI-ARIA listbox pattern — this collapsible group header is an option that stays non-focusable while the container holds focus and aria-activedescendant tracks the active option.
    // biome-ignore lint/a11y/useKeyWithClickEvents: Enter/Space toggle is handled centrally by the navigation list container, not per header.
    <div
      ref={header.rootRef}
      id={header.itemId}
      role="option"
      aria-selected={false}
      aria-label={`${accessibleLabel}, ${expanded ? collapseLabel : expandLabel} section`}
      data-slot="navigation-list-group-header"
      data-value={headerId}
      data-highlighted={header.isActive ? "" : undefined}
      data-state={expanded ? "open" : "closed"}
      onClick={header.handleClick}
      onFocus={header.handleFocus}
      className={cn(
        isTree
          ? "flex w-full items-center py-0.5 font-mono text-sm cursor-pointer select-none"
          : "flex w-full items-center gap-1 px-3 py-2 text-[11px] uppercase tracking-wider font-mono cursor-pointer select-none",
        header.isActive ? "text-foreground" : "text-muted-foreground hover:text-foreground/80",
      )}
    >
      {isTree && depth > 1 && (
        <span aria-hidden="true" className="text-muted-foreground font-mono">
          {parentLinePrefix}
          {isLast ? "└── " : "├── "}
        </span>
      )}
      <Chevron
        open={expanded}
        size="sm"
        className={cn(isTree && depth > 1 && "mx-1", isTree && depth <= 1 && "mr-1")}
      />
      <span aria-hidden="true">{isTree ? `${label}/` : label}</span>
      {!isTree && count !== undefined && <span aria-hidden="true">({count})</span>}
    </div>
  );
}

